import random
import math
from fractions import Fraction

def gaussian_elimination(matrix):
    n = len(matrix)
    for i in range(n):
        if matrix[i][i] == 0:
            # Find a row to swap with
            for j in range(i + 1, n):
                if matrix[j][i] != 0:
                    matrix[i], matrix[j] = matrix[j], matrix[i]
                    break
            else:
                raise ValueError("Matrix is singular")
        # Eliminate below the pivot
        for j in range(i + 1, n):
            factor = Fraction(matrix[j][i], matrix[i][i])
            for k in range(n):
                matrix[j][k] -= factor * matrix[i][k]

def rank(matrix):
    matrix_copy = [row[:] for row in matrix]
    gaussian_elimination(matrix_copy)
    rank = 0
    for row in matrix_copy:
        if any(row):
            rank += 1
    return rank

def dpll_search_tree_height(cnf):
    variables = set()
    clauses = []
    for clause in cnf:
        variables.update(clause)
        clauses.append(clause)

    def backtrack(model, literals):
        if not literals:
            return True
        literal = literals[0]
        if literal in model:
            return backtrack(model, literals[1:])
        else:
            model[literal] = True
            if backtrack(model, literals[1:]):
                return True
            del model[literal]
            model[-literal] = True
            if backtrack(model, literals[1:]):
                return True
            del model[-literal]
            return False

    max_height = 0
    for literal in variables:
        model = {}
        height = 0
        while not backtrack(model, clauses):
            height += 1
        max_height = max(max_height, height)
    return max_height

def generate_cnf(n, m):
    cnf = []
    variables = list(range(1, n + 1))
    for _ in range(m):
        clause = random.sample(variables, random.randint(1, n))
        cnf.append(clause)
    return cnf

def run_trial(seed: int) -> dict:
